from fizzbuzz import fizzbuzz


class FizzBuzzTest(unittest.TestCase):
    def test_first_fifteen(self):
        self.assertEqual(
            fizzbuzz(15),
            ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz",
             "11", "Fizz", "13", "14", "FizzBuzz"],
        )

    def test_zero_and_negative_give_empty_list(self):
        self.assertEqual(fizzbuzz(0), [])
        self.assertEqual(fizzbuzz(-3), [])

    def test_one(self):
        self.assertEqual(fizzbuzz(1), ["1"])

    def test_length_and_types(self):
        result = fizzbuzz(100)
        self.assertEqual(len(result), 100)
        self.assertTrue(all(isinstance(s, str) for s in result))

    def test_multiples(self):
        result = fizzbuzz(100)
        self.assertEqual(result[30 - 1], "FizzBuzz")
        self.assertEqual(result[99 - 1], "Fizz")
        self.assertEqual(result[100 - 1], "Buzz")
        self.assertEqual(result[98 - 1], "98")


if __name__ == "__main__":
    unittest.main()
